def choose_move(observation):
    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (sx, sy))

    # Defensive helper to clamp to -1/0/1 step towards target
    def step_towards(ax, ay, bx, by):
        dx = 0 if bx == ax else (1 if bx > ax else -1)
        dy = 0 if by == ay else (1 if by > ay else -1)
        return [dx, dy]

    # Pursuit-Evasion mode
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(sx, sy, ox, oy)

        # Evader logic: move to farthest corner to maximize distance from pursuer
        grid_w = observation.get("grid_width", 1)
        grid_h = observation.get("grid_height", 1)
        corners = [
            [0, 0],
            [0, grid_h - 1],
            [grid_w - 1, 0],
            [grid_w - 1, grid_h - 1],
        ]
        # pick corner farthest from pursuer
        target = max(corners, key=lambda item: abs(item[0] - ox) + abs(item[1] - oy))
        return step_towards(sx, sy, target[0], target[1])

    # Territory control mode
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return step_towards(sx, sy, best[0], best[1])

    # Resource collection mode (default path)
    resources = observation.get("resources") or []
    if not resources:
        # move toward opponent to pressure or just towards them defensively
        return step_towards(sx, sy, ox, oy)

    best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
    return step_towards(sx, sy, best[0], best[1])

